// _glossary.js holds the glossary that used to live in _shared.js.
//
// the vendored NVIDIA glossary search (01c/02a/02c/glossary): webSearch over the local
// glossary index and instantAnswer for a single term. Self-contained.

// ── Web search (the vendored NVIDIA glossary index) ──────────────────────────
// A real, ranked search that runs from any page with no key and no lab service.
// The browser fetches a small JSON index of NVIDIA glossary terms shipped with the
// course (assets/glossary_index.json, regenerated by scripts/vendor_glossary.py)
// and ranks it against each term's name, tags, and blurb. We search the glossary
// (not a general web crawler) because it is the only source that is simultaneously
// key-less, runnable from a static page with no proxy, and curated NVIDIA content
// the course can vouch for. `instantAnswer` below is the narrow counterpart: a
// single term's definition when the query names one. Shape:
// { results:[{title, body, href}], count, unreachable }.
let _glossaryIndexP = null;
function _loadGlossaryIndex() {
  if (!_glossaryIndexP) {
    _glossaryIndexP = fetch("assets/glossary_index.json")
      .then(r => { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
      .then(d => Array.isArray(d.terms) ? d.terms : [])
      .catch(e => { _glossaryIndexP = null; throw e; });   // let a later call retry
  }
  return _glossaryIndexP;
}
// The unified materials catalog (assets/materials_index.json): the cached glossary terms PLUS the
// on-demand materials (papers, blogs) pulled by scripts/pull_materials.py, one searchable list with
// a tier on each. webSearch ranks over THIS, so the on-demand materials are reachable through the
// same surface; instantAnswer stays glossary-only (it answers with a single definition).
let _materialsCatalogP = null;
function _loadMaterialsCatalog() {
  if (!_materialsCatalogP) {
    _materialsCatalogP = fetch("assets/materials_index.json")
      .then(r => { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
      .then(d => Array.isArray(d.entries) ? d.entries : [])
      .catch(e => { _materialsCatalogP = null; throw e; });   // let a later call retry
  }
  return _materialsCatalogP;
}
// Score one term against the query: an exact or substring name match ranks highest,
// then per-token hits on the name, tags, and blurb. Zero means no match.
//
// A match must touch the term's identity (its name or tags). A query token that only
// appears in the blurb refines the ranking but cannot make a match on its own, so a
// research query about a topic the glossary does not name comes back empty instead of
// surfacing whichever definition happens to share one word. ("production cli sandboxing"
// used to return Machine Learning Operations on the lone word "production" in its blurb.)
function _scoreGlossaryTerm(term, query) {
  const q = query.trim().toLowerCase();
  if (!q) return 0;
  const name  = (term.term  || "").toLowerCase();
  const blurb = (term.blurb || "").toLowerCase();
  const tags  = (term.tags  || []).map(t => String(t).toLowerCase());
  let identity = 0, blurb_score = 0;
  if (name === q) identity += 100;
  else if (name.includes(q) || q.includes(name)) identity += 40;
  for (const tok of q.split(/[^a-z0-9]+/).filter(Boolean)) {
    if (name.includes(tok))               identity += 12;
    if (tags.some(t => t.includes(tok)))  identity += 6;
    if (blurb.includes(tok))              blurb_score += 3;
  }
  return identity > 0 ? identity + blurb_score : 0;
}
// Exposed for the glossary explorer (web/nemoclaw/glossary.html): it reuses the real ranking
// and index loader so its simulation is exactly what the agent's web_search runs, not a copy.
export { _scoreGlossaryTerm as glossaryScore, _loadGlossaryIndex as loadGlossaryIndex,
         _loadMaterialsCatalog as loadMaterialsCatalog };

export async function webSearch(query, { maxResults = 5 } = {}) {
  /* @doc <code>helpers.webSearch(q, {maxResults})</code> ::
       Key-less, ranked search over the course's materials catalog
       (<code>assets/materials_index.json</code>): the cached NVIDIA glossary terms
       <em>plus</em> the on-demand materials (papers, blogs) vendored from the web. Matches the
       query against each entry's name, tags, and blurb; runs from any page with no key and no
       lab. Each result carries a <code>tier</code> (<code>cached</code> = full text shipped;
       <code>on_demand</code> = follow <code>href</code> for the source). Returns <code>{
       results: [{title, body, href, tier, kind}], count, unreachable }</code>.
  */
  try {
    const entries = await _loadMaterialsCatalog();
    const results = entries
      .map(t => ({ t, s: _scoreGlossaryTerm(t, query) }))
      .filter(x => x.s > 0)
      .sort((a, b) => b.s - a.s)
      .slice(0, maxResults)
      .map(x => ({ title: x.t.term, body: x.t.blurb || "", href: x.t.url, tier: x.t.tier, kind: x.t.kind }));
    return { unreachable: false, source: "materials", query, results, count: results.length };
  } catch (e) {
    return { unreachable: true, source: "materials", error: e.message, query, results: [], count: 0 };
  }
}

// ── Instant answer (a single NVIDIA glossary term) ───────────────────────────
// The narrow counterpart to `webSearch`. It returns ONE curated definition, and
// only when the query names a glossary term closely enough to be unambiguous, the
// way an instant-answer box answers "RAG" or "deep agents" but not a full
// question. Most free-form research queries come back empty, so reach for
// `webSearch` to ground answers and use this only to show a narrow, entity-keyed
// lookup behind the same tool contract. Same {results:[{title,body,href}], count,
// unreachable} shape, over the same shipped glossary index.
export async function instantAnswer(query) {
  /* @doc <code>helpers.instantAnswer(q)</code> ::
       A single NVIDIA glossary definition for a query that names a term (e.g.
       <code>retrieval-augmented generation</code>, <code>deep agents</code>). Same return shape
       as <code>webSearch</code>, but it returns one curated card only for a close term match
       and nothing for a free-form question. The narrow, entity-keyed counterpart to
       <code>webSearch</code>.
  */
  try {
    const terms = await _loadGlossaryIndex();
    const q = query.trim().toLowerCase();
    // Entity-keyed: accept only a near-exact name match (the term name contains the
    // whole query or vice versa), so a full question returns nothing the way an
    // instant-answer endpoint would. Prefer the term whose name length is closest.
    const hit = terms
      .map(t => ({ t, name: (t.term || "").toLowerCase() }))
      .filter(x => x.name && (x.name === q || x.name.includes(q) || q.includes(x.name)))
      .sort((a, b) => Math.abs(a.name.length - q.length) - Math.abs(b.name.length - q.length))[0];
    if (!hit) return { unreachable: false, source: "glossary-term", query, results: [], count: 0 };
    const results = [{ title: hit.t.term, body: hit.t.blurb || "", href: hit.t.url }];
    return { unreachable: false, source: "glossary-term", query, results, count: results.length };
  } catch (e) {
    return { unreachable: true, source: "glossary-term", error: e.message, query, results: [], count: 0 };
  }
}
